from taf.internal.gnb.oam.coam.vdu.client.fm.v2 import (
    ApiClient,
    Configuration,
    FmApi,
    ApiException
)

from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.services.fm.http_client_v2 import FMv2HttpClient
from taf.gnb.oam.coam.vdu.utilities.paging import get_alarms_from_all_pages
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1


@auto_token_refresh(api_exception=ApiException)
class FMv2:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self.fm_api_v2 = FmApi(api_client)
        self.local_client = FMv2HttpClient(base_url=con_details.base_url,
                                           connection_alias=con_details.alias)

    def vdu_get_active_alarm(self, timeout=30, paging=True, **kwargs):
        if paging:
            return self.fm_api_v2.get_active_alarms(_request_timeout=timeout, **kwargs)
        else:
            return get_alarms_from_all_pages(
                instance=self.local_client, alarm_type="active", timeout=timeout, **kwargs
            )

    def vdu_get_historical_alarms(self, timeout=30, paging=False, page_number=None, items_per_page=None, **kwargs):
        if not paging:
            return get_alarms_from_all_pages(
                instance=self.local_client, alarm_type="historical", timeout=timeout, **kwargs
            )
        else:
            if page_number and items_per_page:
                return self.local_client.get_historical_alarms(page_number=page_number, items_per_page=items_per_page,
                                                               timeout=timeout, **kwargs)
            else:
                raise ValueError('page_number and items_per_page must be provided when paging is set to True.')
